let historyChart = null;
let currentFilter = 'all';

document.addEventListener('DOMContentLoaded', function() {
    updateSummaryStats();
    setupSearch();
    updateRelativeTimes();

    // Actualizar tiempos relativos cada minuto
    setInterval(updateRelativeTimes, 60000);
});

// Actualizar estadísticas de resumen
function updateSummaryStats() {
    const rows = document.querySelectorAll('.history-row');
    if (rows.length > 0) {
        const lastRow = rows[0]; // Primera fila (más reciente)
        const lastBN = lastRow.dataset.bn || 0;
        const lastColor = lastRow.dataset.color || 0;
        const lastTotal = lastRow.dataset.total || 0;

        document.getElementById('totalBN').textContent = parseInt(lastBN).toLocaleString();
        document.getElementById('totalColor').textContent = parseInt(lastColor).toLocaleString();
        document.getElementById('totalGeneral').textContent = parseInt(lastTotal).toLocaleString();
    }
}

// Filtrar por estado
function filterByState(state) {
    currentFilter = state;
    const rows = document.querySelectorAll('.history-row');
    let visibleCount = 0;

    // Actualizar botones
    document.querySelectorAll('[onclick^="filterByState"]').forEach(btn => {
        btn.classList.remove('active');
    });
    document.getElementById('filter' + state.charAt(0).toUpperCase() + state.slice(1)).classList.add('active');

    rows.forEach(row => {
        if (state === 'all' || row.dataset.estado === state) {
            row.style.display = '';
            visibleCount++;
        } else {
            row.style.display = 'none';
        }
    });

    updateVisibleCount(visibleCount);
}

// Configurar búsqueda
function setupSearch() {
    const searchInput = document.getElementById('searchInput');
    if (searchInput) {
        searchInput.addEventListener('input', function() {
            const searchTerm = this.value.toLowerCase();
            const rows = document.querySelectorAll('.history-row');
            let visibleCount = 0;

            rows.forEach(row => {
                const fecha = row.dataset.fecha.toLowerCase();
                const remitente = row.dataset.remitente.toLowerCase();
                const estado = row.dataset.estado.toLowerCase();

                const matches = fecha.includes(searchTerm) || 
                              remitente.includes(searchTerm) || 
                              estado.includes(searchTerm);

                const stateMatches = currentFilter === 'all' || row.dataset.estado === currentFilter;

                if (matches && stateMatches) {
                    row.style.display = '';
                    visibleCount++;
                } else {
                    row.style.display = 'none';
                }
            });

            updateVisibleCount(visibleCount);
        });
    }
}

// Limpiar búsqueda
function clearSearch() {
    document.getElementById('searchInput').value = '';
    filterByState(currentFilter);
}

// Actualizar contador visible
function updateVisibleCount(count) {
    document.getElementById('visibleCount').textContent = count;
}

// Ordenar tabla
function sortTable(column) {
    const table = document.getElementById('historyTable');
    const tbody = table.querySelector('tbody');
    const rows = Array.from(tbody.querySelectorAll('.history-row'));

    rows.sort((a, b) => {
        let aVal, bVal;

        switch(column) {
            case 'fecha':
                aVal = new Date(a.dataset.fecha);
                bVal = new Date(b.dataset.fecha);
                break;
            case 'bn':
                aVal = parseInt(a.dataset.bn);
                bVal = parseInt(b.dataset.bn);
                break;
            case 'color':
                aVal = parseInt(a.dataset.color);
                bVal = parseInt(b.dataset.color);
                break;
            case 'total':
                aVal = parseInt(a.dataset.total);
                bVal = parseInt(b.dataset.total);
                break;
            default:
                return 0;
        }

        return bVal - aVal; // Orden descendente
    });

    rows.forEach(row => tbody.appendChild(row));
}

// Togglear gráfico
function toggleChart() {
    const chartSection = document.getElementById('chartSection');
    const isVisible = chartSection.style.display !== 'none';

    if (isVisible) {
        chartSection.style.display = 'none';
    } else {
        chartSection.style.display = 'block';
        if (!historyChart) {
            createChart();
        }
    }
}

// Crear gráfico
function createChart() {
    const ctx = document.getElementById('historyChart').getContext('2d');
    const rows = document.querySelectorAll('.history-row');

    const labels = [];
    const bnData = [];
    const colorData = [];
    const totalData = [];

    // Tomar los últimos 10 registros para el gráfico
    Array.from(rows).slice(0, 10).reverse().forEach(row => {
        labels.push(row.dataset.fecha.split(' ')[0]); // Solo fecha
        bnData.push(parseInt(row.dataset.bn));
        colorData.push(parseInt(row.dataset.color));
        totalData.push(parseInt(row.dataset.total));
    });

    historyChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: 'B/N',
                data: bnData,
                borderColor: '#6c757d',
                backgroundColor: 'rgba(108, 117, 125, 0.1)',
                tension: 0.1
            }, {
                label: 'Color',
                data: colorData,
                borderColor: '#0dcaf0',
                backgroundColor: 'rgba(13, 202, 240, 0.1)',
                tension: 0.1
            }, {
                label: 'Total',
                data: totalData,
                borderColor: '#0d6efd',
                backgroundColor: 'rgba(13, 110, 253, 0.1)',
                tension: 0.1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Evolución de Contadores (Últimos 10 registros)'
                },
                legend: {
                    position: 'top'
                }
            }
        }
    });
}

// Actualizar tiempos relativos
function updateRelativeTimes() {
    document.querySelectorAll('.relative-time').forEach(element => {
        const dateStr = element.dataset.date;
        if (dateStr) {
            element.textContent = getRelativeTime(dateStr);
        }
    });
}

// Calcular tiempo relativo
function getRelativeTime(dateString) {
    try {
        const date = new Date(dateString.replace(/(\d{2})\/(\d{2})\/(\d{4})/, '$3-$2-$1'));
        const now = new Date();
        const diffMs = now - date;
        const diffMins = Math.floor(diffMs / 60000);
        const diffHours = Math.floor(diffMins / 60);
        const diffDays = Math.floor(diffHours / 24);

        if (diffMins < 1) return 'Ahora mismo';
        if (diffMins < 60) return `Hace ${diffMins} min`;
        if (diffHours < 24) return `Hace ${diffHours}h`;
        if (diffDays < 7) return `Hace ${diffDays}d`;
        return `Hace ${Math.floor(diffDays / 7)}sem`;
    } catch (e) {
        return 'Hace un momento';
    }
}

// Copiar datos de fila
function copyRowData(button) {
    const info = button.dataset.info;
    if (navigator.clipboard && info) {
        navigator.clipboard.writeText(info).then(() => {
            showAlert('Datos copiados: ' + info, 'success');
        });
    }
}

// Resaltar fila
function highlightRow(element) {
    const row = element.closest('tr');
    row.classList.toggle('table-warning');
    showAlert('Fila resaltada', 'info');
}

// Comparar fila (placeholder)
function compareRow(element) {
    showAlert('Función de comparación en desarrollo', 'info');
}

// Exportaciones
function exportToCSV() {
    const rows = document.querySelectorAll('.history-row:not([style*="display: none"])');
    let csv = 'Fecha,B/N,Color,Total,Estado,Remitente\\n';

    rows.forEach(row => {
        const fecha = row.dataset.fecha;
        const bn = row.dataset.bn;
        const color = row.dataset.color;
        const total = row.dataset.total;
        const estado = row.dataset.estado;
        const remitente = row.dataset.remitente;

        csv += `"${fecha}","${bn}","${color}","${total}","${estado}","${remitente}"\\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'historial_equipos.csv';
    a.click();
    window.URL.revokeObjectURL(url);

    showAlert('Archivo CSV descargado', 'success');
}

function exportToExcel() {
    showAlert('Función de exportación Excel en desarrollo', 'info');
}

function exportToPDF() {
    showAlert('Función de exportación PDF en desarrollo', 'info');
}

// Función para mostrar alertas
function showAlert(message, type = 'info') {
    const alertDiv = document.createElement('div');
    alertDiv.className = `alert alert-${type} alert-dismissible fade show position-fixed`;
    alertDiv.style.cssText = 'top: 20px; right: 20px; z-index: 9999; min-width: 300px;';
    alertDiv.innerHTML = `

        ${message}

    `;

    document.body.appendChild(alertDiv);

    setTimeout(() => {
        if (alertDiv.parentNode) {
            alertDiv.remove();
        }
    }, 3000);
}

// Función adicional para análisis de datos
function analyzeGrowth() {
    const rows = document.querySelectorAll('.history-row');
    if (rows.length < 2) {
        showAlert('Se necesitan al menos 2 registros para el análisis', 'warning');
        return;
    }

    const first = rows[rows.length - 1]; // Más antiguo
    const last = rows[0]; // Más reciente

    const firstTotal = parseInt(first.dataset.total);
    const lastTotal = parseInt(last.dataset.total);
    const growth = lastTotal - firstTotal;

    const message = growth > 0 ? 
        `Crecimiento: +${growth.toLocaleString()} impresiones` : 
        `Sin crecimiento detectado`;

    showAlert(message, growth > 0 ? 'success' : 'info');
}

// Función para detectar patrones
function detectPatterns() {
    const rows = document.querySelectorAll('.history-row');
    const bnValues = Array.from(rows).map(row => parseInt(row.dataset.bn));
    const colorValues = Array.from(rows).map(row => parseInt(row.dataset.color));

    const bnTrend = bnValues.length > 1 && bnValues[0] > bnValues[bnValues.length - 1];
    const colorTrend = colorValues.length > 1 && colorValues[0] > colorValues[colorValues.length - 1];

    let message = 'Patrones detectados: ';
    if (bnTrend) message += 'Incremento en B/N ';
    if (colorTrend) message += 'Incremento en Color ';
    if (!bnTrend && !colorTrend) message += 'Sin patrones claros';

    showAlert(message, 'info');
}

// Agregar botones de análisis al cargar
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(() => {
        const cardFooter = document.querySelector('.card-footer');
        if (cardFooter) {
            const analysisButtons = document.createElement('div');
            analysisButtons.className = 'mt-3 text-center';
            analysisButtons.innerHTML = `

                    Analizar Crecimiento


                    Detectar Patrones

            `;
            cardFooter.appendChild(analysisButtons);
        }
    }, 100);
});
